local config = {
  ui_story_30360401_1_dialog_content = "Então... Qual é o problema?",
  ui_story_30360401_2_dialog_content = "<color=#e8d9bb>Depois que a escuridão caiu, fechei os olhos e caí num sono profundo.</color>",
  ui_story_30360401_3_dialog_content = "Mas acordei no meio da noite com um par de olhos brilhando no escuro...",
  ui_story_30360401_4_dialog_content = "Eu tinha certeza de que o que estava diante de mim era uma besta...",
  ui_story_30360401_5_dialog_content = "Quer dizer, um lobo estava te observando ontem à noite?",
  ui_story_30360401_6_dialog_content = "Sim, acredito que possa ser um dos seus lobos das sombras.",
  ui_story_30360401_7_dialog_content = "Isso é impossível... Eu não usei minha magia das sombras, nem ordenei que nenhum dos meus lobos das sombras fizesse isso.",
  ui_story_30360401_8_dialog_content = "Eu sei... Não estou duvidando de você.",
  ui_story_30360401_9_dialog_content = "Mas isso tem acontecido há tantos dias que preciso falar com você sobre isso.",
  ui_story_30360401_10_option_content = "Embora eu não tenha nenhuma prova...",
  ui_story_30360401_11_dialog_content = "Porque eu podia sentir isso.",
  ui_story_30360401_12_dialog_content = "Você quer dizer, através de sua habilidade psíquica?",
  ui_story_30360401_13_dialog_content = "Bem, então pode ser eles.",
  ui_story_30360401_14_option_content = "Tenho certeza de que era um lobo sombrio.",
  ui_story_30360401_15_dialog_content = "É possível que eles ajam sem a sua permissão? Eles poderiam estar vagando livremente enquanto você descansa?",
  ui_story_30360401_16_dialog_content = "Eu não sei... Talvez?",
  ui_story_30360401_17_dialog_content = "Ei, por que você foi ao quarto de PlayerName ontem à noite?",
  ui_story_30360401_18_dialog_content = "<color=#e8d9bb>Os lobos das sombras curvam suas orelhas.</color>",
  ui_story_30360401_19_dialog_content = "Parece que você estava certo.",
  ui_story_30360401_20_dialog_content = "Como você sabe disso?",
  ui_story_30360401_21_dialog_content = "Só posso dizer pelas suas reações físicas, como a maneira como suas orelhas se mexem.",
  ui_story_30360401_22_dialog_content = "Afinal, eu não sou como você. Eu não consigo falar com animais.",
  ui_story_30360401_23_dialog_content = "Não, não, não é bem assim... Além disso, eles contam como animais...?",
  ui_story_30360401_24_dialog_content = "De qualquer forma, você pode, por favor, ficar de olho nos seus lobos das sombras? Pelo menos os impeça de entrar no meu quarto e ficar me encarando no meio da noite.",
  ui_story_30360401_25_dialog_content = "Tá bom.",
  ui_story_30360401_26_dialog_content = "Você está proibido de entrar no quarto de PlayerName.",
  ui_story_30360401_27_dialog_content = "<color=#e8d9bb>Os lobos das sombras não mostram nenhuma reação.</color>",
  ui_story_30360401_28_dialog_content = "Eles se desligaram.",
  ui_story_30360401_29_option_content = "Espere... Por quê?",
  ui_story_30360401_30_dialog_content = "Como eu vou saber? Provavelmente eles têm suas próprias razões.",
  ui_story_30360401_31_dialog_content = "Isso significa que eles continuarão vindo ao meu quarto para me encarar no meio da noite?",
  ui_story_30360401_32_dialog_content = "Provavelmente.",
  ui_story_30360401_33_dialog_content = "Isso é preocupante... Como posso dormir assim?",
  ui_story_30360401_32_option_content = "Não, não... Você precisa convencê-los!",
  ui_story_30360401_35_dialog_content = "Como posso persuadi-los?",
  ui_story_30360401_36_dialog_content = "Por que você está me perguntando? Você não é o mestre deles?",
  ui_story_30360401_37_dialog_content = "Não consegui ensinar a eles nenhum comando além de atacar. Se eles não me ouvirem de jeito nenhum, não há nada que eu possa fazer.",
  ui_story_30360401_38_dialog_content = "O que eu faço?",
  ui_story_30360401_39_dialog_content = "Você não consegue se conectar com eles psiquicamente? Tente se comunicar com eles.",
  ui_story_30360401_40_option_content = "É um pouco assustador.",
  ui_story_30360401_41_dialog_content = "Como é intimidante?",
  ui_story_30360401_42_dialog_content = "Eles parecem feras misteriosas, e estão registrados no banco de dados do Colosso como criaturas perigosas, sem mencionar o fato de que nasceram de suas habilidades.",
  ui_story_30360401_43_dialog_content = "Se eles podem ser considerados entidades viáveis psiquicamente ainda é desconhecido para mim. Não tenho confiança se posso me comunicar com eles.",
  ui_story_30360401_44_dialog_content = "Eu adquiri a habilidade do Lobo Sombrio em ruínas desconhecidas. Eu nem mesmo sei o que eles são...",
  ui_story_30360401_45_dialog_content = "Você pode considerá-los como criaturas mágicas, mas para mim eles são apenas como cães comuns.",
  ui_story_30360401_46_option_content = "Tenho certeza que não tem problema em apenas tentar...",
  ui_story_30360401_47_dialog_content = "Eles parecem cachorrinhos fofos, embora não pareçam exatamente iguais aos registrados no banco de dados de Soroz.",
  ui_story_30360401_48_dialog_content = "<color=#e8d9bb>Os lobos das sombras começam a mostrar seus dentes.</color>",
  ui_story_30360401_49_dialog_content = "Cuidado! Mantenha sua distância... Eles estão ficando inquietos.",
  ui_story_30360401_50_dialog_content = "Não toque neles tão repentinamente. Embora possam ser chamados de Lobos Sombrios, ainda não sabemos exatamente de onde essas criaturas mágicas vêm.",
  ui_story_30360401_51_dialog_content = "Não faça nada para provocá-los, ou eles podem atacar você.",
  ui_story_30360401_52_dialog_content = "Espere um minuto. Essa é a sua habilidade, e é tudo que você tem a dizer sobre elas?",
  ui_story_30360401_53_dialog_content = "Adquiri essa habilidade, mas não a estudei profundamente. Tudo que sei é que posso usá-la.",
  ui_story_30360401_54_dialog_content = "Então é melhor eu manter minha distância.",
  ui_story_30360401_55_dialog_content = "<color=#e8d9bb>Você fecha os olhos novamente e retorna à escuridão, bloqueando interferências externas. Então, você começa a se concentrar...</color>",
  ui_story_30360401_56_dialog_content = "Embora eu possa usar minha habilidade psíquica neles, ainda não consigo iniciar uma conversa, como esperado...",
  ui_story_30360401_57_dialog_content = "Espere... De repente estou sentindo uma imagem!",
  ui_story_30360401_58_dialog_content = "É um lobo sombrio... Não, há mais de um...",
  ui_story_30360401_59_dialog_content = "Parece que Hydrad está entre eles!",
  ui_story_30360401_60_dialog_content = "Você também esteve no meu quarto!?",
  ui_story_30360401_61_dialog_content = "...",
  ui_story_30360401_62_dialog_content = "Fala alguma coisa!",
  ui_story_30360401_63_dialog_content = "Você respondeu todas as minhas perguntas até agora.\nNão acha que é obviamente culpado?",
  ui_story_30360401_64_dialog_content = "Por favor, me ajude a entender o que está acontecendo aqui.",
  ui_story_30360401_65_dialog_content = "Hmm... Eu fui ao seu quarto. E daí?",
  ui_story_30360401_66_dialog_content = "Você é o responsável por tudo isso e nem sequer se sente culpado!?",
  ui_story_30360401_67_dialog_content = "Por que você disse que era impossível agora mesmo? Você está tentando me enganar culpando os lobos das sombras?",
  ui_story_30360401_68_dialog_content = "Você achou que poderia esconder a verdade de mim fingindo ajudar a resolver o problema?",
  ui_story_30360401_69_dialog_content = "Assim que eu senti, eu sabia!",
  ui_story_30360401_70_dialog_content = "Não, eu te disse... Não fui eu ontem à noite. Eu só estive no seu quarto uma vez!",
  ui_story_30360401_71_dialog_content = "Você também consegue ver isso?",
  ui_story_30360401_72_dialog_content = "Por quê? Quando você foi lá?",
  ui_story_30360401_73_dialog_content = "Apenas no dia em que cheguei pela primeira vez ao Colosso. Eu fui observar você.",
  ui_story_30360401_74_dialog_content = "O motivo é muito simples. Desde que decidi ir com você, achei que deveria pelo menos saber quem você é.",
  ui_story_30360401_75_dialog_content = "Espere... Meu instinto está me dizendo que o motivo de eles estarem agindo por vontade própria é você.",
  ui_story_30360401_76_dialog_content = "Algo tem te incomodado recentemente?",
  ui_story_30360401_77_dialog_content = "Você já ouviu essas palavras: \"A sombra está te observando\"?",
  ui_story_30360401_78_option_content = "Já.",
  ui_story_30360401_79_dialog_content = "Essas palavras têm se espalhado por Umbraton? Lembro que algumas pessoas de Umbraton já falaram sobre isso.",
  ui_story_30360401_80_dialog_content = "Bem, você deveria prestar um pouco mais de atenção nisso.",
  ui_story_30360401_81_dialog_content = "Se você conseguir ver a verdade através do nevoeiro, quero dizer.",
  ui_story_30360401_82_option_content = "Não.",
  ui_story_30360401_83_dialog_content = "Essas palavras circulando por Umbraton são mais do que apenas um boato mundano. Vá e pergunte a mais pessoas e você saberá.",
  ui_story_30360401_84_dialog_content = "Então, o que isso tem a ver com alguma coisa?",
  ui_story_30360401_85_dialog_content = "Não consigo descrever para você. Você é o clarividente. Você precisa ver por si mesmo.",
  ui_story_30360401_86_dialog_content = "Tudo que posso te dizer é que as sombras prestam atenção em você porque gostam do seu cheiro.",
  ui_story_30360401_87_dialog_content = "Não apenas os lobos das sombras... Haverá muitos mais por vir.",
  ui_story_30360401_88_dialog_content = "Espere, você quer dizer... Os lobos das sombras ainda virão ao meu quarto?",
  ui_story_30360401_89_dialog_content = "E que haverá mais criaturas chegando...",
  ui_story_30360401_90_dialog_content = "Provavelmente.",
  ui_story_30360401_91_dialog_content = "Você vai se acostumar com isso nos próximos dias. Os lobos das sombras logo irão embora assim que se cansarem de vigiar você.",
  ui_story_30360401_92_dialog_content = "Isso não vai funcionar. Já é demais para aguentar, e provavelmente só vai piorar.",
  ui_story_30360401_93_dialog_content = "Por quê?",
  ui_story_30360401_94_dialog_content = "Como... Como você consegue de repente virar essa conversa ao contrário!?",
  ui_story_30360401_95_dialog_content = "Se esses animais selvagens insistirem em me observar enquanto durmo, é claro, vou me sentir assustado.",
  ui_story_30360401_96_dialog_content = "Você vê os lobos das sombras como uma ameaça à sua segurança?",
  ui_story_30360401_97_dialog_content = "Talvez.",
  ui_story_30360401_98_dialog_content = "Como está a situação, até você não sabe o que eles podem fazer sem a sua autorização. Como você pode garantir que eles não vão me atacar?",
  ui_story_30360401_99_dialog_content = "Isso é um problema sério... Por isso vim pedir se você poderia ajudar.",
  ui_story_30360401_100_dialog_content = "Eles só querem dar uma olhada mais de perto no que você é. Basta pensar neles como cães curiosos e você ficará bem.",
  ui_story_30360401_101_dialog_content = "No entanto, como isso está te incomodando, eu não posso simplesmente ignorar. Afinal, até certo ponto, isso é culpa minha.",
  ui_story_30360401_102_dialog_content = "A partir de hoje, vou vigiá-los à noite. Se insistirem em ir para o seu quarto, tentarei impedi-los.",
  ui_story_30360401_103_dialog_content = "Se eu não conseguir impedi-los, eu vou junto.",
  ui_story_30360401_104_dialog_content = "Espere! Onde está a lógica nisso?",
  ui_story_30360401_105_dialog_content = "Se apenas os lobos das sombras forem ao seu quarto, você pode se sentir ameaçado. Então eu vou e garanto que eles não façam nada com você.",
  ui_story_30360401_106_dialog_content = "Não vamos deixar mais nada te machucar.",
  ui_story_30360401_107_dialog_content = "Seus problemas estão resolvidos. Pronto.",
  ui_story_30360201_X1_dialog_content = "Do que vocês estão falando?",
  ui_story_30360201_1_dialog_content = "O que você está fazendo aqui? Você não foi para Lumópolis!?",
  ui_story_30360201_2_dialog_content = "Hm? Eu...",
  ui_story_30360201_3_dialog_content = "Valente navegador, por que você veio aqui?",
  ui_story_30360201_4_dialog_content = "Então, você está de volta aos seus velhos truques? Fique longe de PlayerName!",
  ui_story_30360201_5_dialog_content = "O quê? Você acha que eu machucaria PlayerName?",
  ui_story_30360201_6_dialog_content = "Eu só quero conversar com PlayerName, na sua frente.",
  ui_story_30360201_7_dialog_content = "Impossível. Não vamos ficar aqui e ouvir suas mentiras.",
  ui_story_30360201_8_dialog_content = "Hmm? Por que não devemos ouvir o Sr. Kleken?",
  ui_story_30360201_9_dialog_content = "Você será arrastado para um abismo de engano... Você acha que ele está apenas brincando com você?",
  ui_story_30360201_10_dialog_content = "Bem, eu gosto de uma boa piada.",
  ui_story_30360201_11_dialog_content = "Mas Kleken não está alinhado com o Senhor Sombrio?",
  ui_story_30360201_12_dialog_content = "Tecnicamente, vocês dois estão trabalhando juntos, não?",
  ui_story_30360201_13_dialog_content = "Essa não é a questão.",
  ui_story_30360201_14_dialog_content = "Lembre-se disso, você não pode sempre acreditar nas palavras dos outros.",
  ui_story_30360201_15_dialog_content = "Se você fosse levado por tal charlatão na minha presença, eu nunca me perdoaria.",
  ui_story_30360201_16_dialog_content = "A Viagem de Chihiro?",
  ui_story_30360201_17_dialog_content = "Talvez. Isso é o que eu acho, de qualquer forma.",
  ui_story_30360201_18_dialog_content = "Hmm... De repente me colocando no chão, bem na minha frente? Isso é interessante.",
  ui_story_30360201_19_dialog_content = "Você ainda tá aqui?",
  ui_story_30360201_20_dialog_content = "E você quer que eu saia?",
  ui_story_30360201_21_dialog_content = "Bem, esta é agora minha seção.",
  ui_story_30360201_22_dialog_content = "Tudo bem, vou indo.",
  ui_story_30360201_23_dialog_content = "As coisas estão tão ruins entre vocês dois?",
  ui_story_30360201_24_dialog_content = "Apenas moderadamente ruim.",
  ui_story_30360201_25_dialog_content = "Estou um pouco curioso para saber o que está acontecendo com você.",
  ui_story_30360201_26_dialog_content = "Nós simplesmente não temos personalidades muito compatíveis...",
  ui_story_30360201_27_dialog_content = "<color=#e8d9bb>A primeira vez que se viram nas favelas, os olhares desses dois sujos moleques de rua não se encontraram e ambos permaneceram em silêncio.</color>",
  ui_story_30360201_28_dialog_content = "<color=#e8d9bb>A segunda vez que se viram em meio ao caos do campo de batalha, seus olhares não se encontraram e ambos permaneceram em silêncio.</color>",
  ui_story_30360201_29_dialog_content = "<color=#e8d9bb>Na terceira vez que se viram, um estava à esquerda do Senhor das Sombras, e o outro à direita do Senhor das Sombras.</color>",
  ui_story_30360201_30_dialog_content = "<color=#e8d9bb>Um em uma longa túnica, outro em roupas finas, seus olhares não se encontraram e ambos permaneceram em silêncio.</color>",
  ui_story_30360201_31_dialog_content = "<color=#e8d9bb>A quarta vez, a quinta vez... seus olhares não se encontraram e ambos permaneceram em silêncio.</color>",
  ui_story_30360201_32_dialog_content = "<color=#e8d9bb>Até...</color>",
  ui_story_30360201_33_dialog_content = "Provavelmente é por causa daquela vez. Deixe-me te contar.",
  ui_story_30360201_34_dialog_content = "Não interrompa...",
  ui_story_30360201_35_dialog_content = "Huh? Você não vai embora?",
  ui_story_30360201_36_dialog_content = "Eu estava apenas brincando. Na verdade...",
  ui_story_30360201_37_dialog_content = "Deixe-o ir. Eu te direi.",
  ui_story_30360201_38_option_content = "Ah, Sr. Kleken, você se importaria de sair primeiro?",
  ui_story_30360201_39_dialog_content = "Sinto que os lobos das sombras já mostraram seus dentes, e isso me preocupa...",
  ui_story_30360201_40_dialog_content = "Claro, se você insistir, eu vou embora.",
  ui_story_30360201_41_dialog_content = "Perdoe minha falta de educação. Por favor, continue.",
  ui_story_30360201_42_option_content = "Isso é necessário?...",
  ui_story_30360201_43_dialog_content = "Claro, isso não é necessário, meu gentil herói.",
  ui_story_30360201_44_dialog_content = "<color=#e8d9bb>O lobo sombrio ao lado de Hydrad começa a rosnar...</color>",
  ui_story_30360201_45_dialog_content = "Seu pequeno filhote de lobo parece bravo...",
  ui_story_30360201_46_dialog_content = "Você deveria sair daqui antes que eu fique com raiva.",
  ui_story_30360201_47_dialog_content = "Não se preocupe, eu consigo captar uma dica.",
  ui_story_30360201_48_dialog_content = "Não vou tornar isso mais constrangedor para PlayerName do que já é. Até a próxima vez, herói.",
  ui_story_30360201_49_dialog_content = "Acho que ele realmente se mandou desta vez.",
  ui_story_30360201_50_dialog_content = "Você parece um pouco bravo hoje?",
  ui_story_30360201_51_dialog_content = "Por que você veio aqui de repente? Você não saiu a negócios?",
  ui_story_30360201_52_dialog_content = "Kleken me pediu para vir.",
  ui_story_30360201_53_dialog_content = "<size=45>Aquele cara de novo!</size>",
  ui_story_30360201_54_dialog_content = "O que ele disse para você?",
  ui_story_30360201_55_dialog_content = "Bem, ele apenas diria para ir e dar uma olhada em outro lugar em algumas ocasiões.",
  ui_story_30360201_56_dialog_content = "Porque ele mencionou o Colosso desta vez, eu só vim para conferir.",
  ui_story_30360201_57_dialog_content = "Desculpe... Isso parece ser um motivo bastante confuso, não é?",
  ui_story_30360201_58_dialog_content = "Não... Não é esse o motivo.",
  ui_story_30360201_59_dialog_content = "Bem, vamos voltar ao ponto. Então, o que aconteceu entre vocês dois?",
  ui_story_30360201_60_dialog_content = "Sinto que você estava se lembrando de suas memórias passadas agora mesmo?",
  ui_story_30360201_61_dialog_content = "Mas não é nada importante...",
  ui_story_30360201_62_dialog_content = "<color=#e8d9bb>Até a primeira conversa deles.</color>",
  ui_story_30360201_63_dialog_content = "Procurando pelo Senhor Sombrio? Ele pode estar em Lumópolis.",
  ui_story_30360201_64_dialog_content = "Você está procurando pelo Senhor Sombrio? Ele pode estar em Lumópolis.",
  ui_story_30360201_65_dialog_content = "A primeira vez que falei com ele, ele mentiu para mim.",
  ui_story_30360201_66_dialog_content = "É isso? É o fim da história?",
  ui_story_30360201_67_dialog_content = "Se você quer dizer algo, desembucha. Eu não me importo e posso ouvir.",
  ui_story_30360201_68_dialog_content = "Desculpe...",
  ui_story_30360201_69_dialog_content = "Ahem... Então você quer dizer que Kleken te contou uma mentira na primeira vez que falou com ele?",
  ui_story_30360201_70_dialog_content = "Sim.",
  ui_story_30360201_71_option_content = "Então, o Shadowlord não estava em Lumopolis naquele dia?",
  ui_story_30360201_72_dialog_content = "Esperei lá o dia todo, até mesmo os guardas vieram.",
  ui_story_30360201_73_dialog_content = "Dei uma surra neles antes de voltar.",
  ui_story_30360201_74_dialog_content = "Mais tarde, o Senhor Sombrio me disse que ele normalmente não vai a Lumopolis, então era uma mentira completa.",
  ui_story_30360201_75_option_content = "Você acreditou nele?",
  ui_story_30360201_76_dialog_content = "Acreditei nele, fui lá, e não encontrei nada.",
  ui_story_30360201_77_dialog_content = "Entendo...",
  ui_story_30360201_78_dialog_content = "Eu também bati nos Guardas Lumo, causando alguns problemas.",
  ui_story_30360201_79_dialog_content = "Espere... Por que você espancou os guardas?",
  ui_story_30360201_80_dialog_content = "Porque eles foram muito rudes comigo.",
  ui_story_30360201_81_dialog_content = "Ele está agachado lá com seus cachorros o dia todo...",
  ui_story_30360201_82_dialog_content = "Presumo que ele vai pedir aos nobres para acolhê-lo, certo? Tantas pessoas estão fazendo isso hoje em dia...",
  ui_story_30360201_83_dialog_content = "Mas trazer os cachorros também? Agora, isso é pedir um pouco demais!",
  ui_story_30360201_84_dialog_content = "Eu só quero que eles calem a boca!",
  ui_story_30360201_85_dialog_content = "Ah, então foi culpa dos guardas.",
  ui_story_30360201_86_dialog_content = "Sobre Kleken mentindo para você...",
  ui_story_30360201_87_option_content = "Talvez você seja parcialmente responsável...",
  ui_story_30360201_88_dialog_content = "Tipo... por acreditar em uma mentira tão óbvia?",
  ui_story_30360201_89_dialog_content = "Se eu confiasse em você, seria minha culpa?",
  ui_story_30360201_90_dialog_content = "Não é isso que estou dizendo!",
  ui_story_30360201_91_dialog_content = "Ele foi o culpado!",
  ui_story_30360201_92_dialog_content = "Vê, eu normalmente não acredito em nada do que ele diz, a menos que eu sinta a sensação certa!",
  ui_story_30360201_93_dialog_content = "Mesmo que isso tenha soado um tanto estranho.",
  ui_story_30360201_94_option_content = "Foi inteiramente culpa dele!",
  ui_story_30360201_95_dialog_content = "O Sr. Kleken gosta de contar mentiras sem sentido.",
  ui_story_30360201_96_dialog_content = "Ele se refere a si mesmo como um vigarista, mas também adverte as pessoas para não confiarem nele.",
  ui_story_30360201_97_dialog_content = "Então, não acredite em nada que ele diz novamente, e leve cada uma de suas palavras com um grão de sal.",
  ui_story_30360201_98_dialog_content = "...",
  ui_story_30360201_99_dialog_content = "O-o que é isso? Seu silêncio está me machucando...",
  ui_story_30360201_100_dialog_content = "Por favor, perdoe meu silêncio... É só que você superou minhas expectativas.",
  ui_story_30360201_101_dialog_content = "Inicialmente, eu queria te alertar para não se deixar enganar pelas palavras dele.",
  ui_story_30360201_102_dialog_content = "Parece que você é muito mais perspicaz do que eu imaginava.",
  ui_story_30360201_103_dialog_content = "Obrigado pela sua preocupação, mas não acho que ele fará algo errado comigo.",
  ui_story_30360201_104_dialog_content = "Além disso, eu não sei se dizer uma coisa dessas seria um pouco intrometido.",
  ui_story_30360201_105_dialog_content = "Não quero que exista nenhum conflito entre aqueles que vêm para viver a bordo do Colossus.",
  ui_story_30360201_106_dialog_content = "Então...",
  ui_story_30360201_107_dialog_content = "Eu sei.",
  ui_story_30360201_108_dialog_content = "Você está certo e não é intrometido. Não há necessidade de duvidar de si mesmo.",
  ui_story_30360201_109_dialog_content = "Maravilhoso. Então, já que todos nós estamos trabalhando e vivendo juntos no Colosso, devemos tentar nos dar bem uns com os outros no futuro!",
  ui_story_30360201_110_dialog_content = "Não posso.",
  ui_story_30360201_111_dialog_content = "Espere... Eu pensei que tínhamos acabado de concordar?",
  ui_story_30360201_112_dialog_content = "Eu não concordei com nada.",
  ui_story_30360201_113_dialog_content = "Agora que penso nisso, você sempre parece terminar as conversas com esse tipo de indiferença severa.",
  ui_story_30360201_114_dialog_content = "Estou quase me acostumando com isso.",
  ui_story_30360201_115_dialog_content = "Você deve ter outros assuntos para tratar... Eu sei que certamente tenho. Adeus.",
  ui_story_30360201_116_dialog_content = "Hã?",
  ui_story_30360201_117_dialog_content = "O quê? Ele saiu?",
  ui_story_30360201_118_dialog_content = "\"Adeus\", huh? Quer eu goste ou não, acabarei encontrando você ou aquele cara novamente.",
  ui_story_30360201_119_dialog_content = "Do nada de novo!",
  ui_story_30360201_120_dialog_content = "Se um relacionamento deve mudar, ele mudará naturalmente. Se não for para mudar, você não deve forçá-lo.",
  ui_story_30360201_121_dialog_content = "Por exemplo, as coisas nunca vão melhorar entre mim e essa praga.",
  ui_story_30360201_122_dialog_content = "Antes de você chegar, tive outra conversa infeliz com ele. O que aconteceu foi...",
  ui_story_30360201_123_dialog_content = "Não você de novo, seu polvo. Você viu...",
  ui_story_30360201_124_dialog_content = "Ah, talvez você possa encontrar PlayerName em Lumópolis.",
  ui_story_30360201_125_dialog_content = "O que você disse?!",
  ui_story_30360201_126_dialog_content = "Do que vocês estão falando?",
  ui_story_30360201_127_dialog_content = "O que você está fazendo aqui? Você não foi para Lumópolis!?",
  ui_story_30360201_128_dialog_content = "Assim como o polvo continua sendo tão enganador como antes...",
  ui_story_30360201_129_dialog_content = "Se você não tivesse aparecido a tempo, eu teria ido para Lumópolis...",
  ui_story_30360601_1_dialog_content = "<color=#e8d9bb>Na sombra de uma rua sem nome, fica um armazém escurecido cheio de jaulas de animais. De trás de suas grades brilham inúmeros pares de olhos ameaçadores.</color>",
  ui_story_30360601_2_dialog_content = "<color=#e8d9bb>E nas profundezas do armazém, separado por uma cortina esfarrapada—</color>",
  ui_story_30360601_3_dialog_content = "<color=#e8d9bb>Tapa!</color>",
  ui_story_30360601_4_dialog_content = "...",
  ui_story_30360601_5_dialog_content = "Ainda não vai falar, hein? Você é duro de quebrar, eu admito isso.",
  ui_story_30360601_6_dialog_content = "É assim que você os trata também?",
  ui_story_30360601_7_dialog_content = "Está brincando? Estamos falando de mercadoria valiosa! Uma escória inútil como você nem se compara!",
  ui_story_30360601_8_dialog_content = "\"Mercadoria\", huh? Entendi... Parece que terei que te levar à justiça afinal.",
  ui_story_30360601_9_dialog_content = "<color=#e8d9bb>Algum tempo antes</color>",
  ui_story_30360601_10_dialog_content = "Então realmente é você, Hydrad! Há quanto tempo!",
  ui_story_30360601_11_dialog_content = "PlayerName? Você não poderia ter escolhido um pior momento para aparecer.",
  ui_story_30360601_12_dialog_content = "Você usou suas habilidades psíquicas para me encontrar? Deixa pra lá, tenho algo importante para resolver agora.",
  ui_story_30360601_13_dialog_content = "O que foi? Uau! É aquele...",
  ui_story_30360601_14_dialog_content = "Sim. Como você pode ver, é um <color=#FFB400>lobo selvagem</color>.",
  ui_story_30360601_15_dialog_content = "Um lobo selvagem? Eu nunca vi um antes... Ele parece um pouco com seus Lobos Sombrios, não parece?",
  ui_story_30360601_16_dialog_content = "De onde exatamente você veio?",
  ui_story_30360601_17_dialog_content = "Eu? Bem, eu—",
  ui_story_30360601_18_dialog_content = "Eu quis dizer o lobo.",
  ui_story_30360601_19_dialog_content = "... Espere, você está realmente se comunicando com um lobo agora?",
  ui_story_30360601_20_dialog_content = "Claro que não. Ao contrário de você, eu não consigo falar com animais.",
  ui_story_30360601_21_dialog_content = "<color=#e8d9bb>O lobo solta um rosnado desanimado. Embora seus olhos brilhem ferozmente, seus músculos estão muito fracos para sustentar seu corpo enfraquecido—</color>",
  ui_story_30360601_22_dialog_content = "Esses caras são muito perspicazes. Eles podem discernir os sentimentos de outras pessoas, assim como eu posso discernir o que eles estão pensando.",
  ui_story_30360601_23_dialog_content = "Os lobos são animais de alcateia, mas este está sozinho, ferido e extremamente desconfiado de mim.",
  ui_story_30360601_24_dialog_content = "Lobos solitários não aparecem do nada em Umbraton. Alguém deve ter trazido isso aqui. Apareçam, Lobos Sombrios.",
  ui_story_30360601_25_dialog_content = "Viu? Você está em boa companhia, agora pare de ser tão cauteloso comigo.",
  ui_story_30360601_26_dialog_content = "Eu preciso que você faça uma pergunta, PlayerName.",
  ui_story_30360601_27_option_content = "O que? Eu?",
  ui_story_30360601_28_dialog_content = "Sim, você. Apenas pergunte o que aconteceu com isso.",
  ui_story_30360601_29_option_content = "Vou tentar, claro...",
  ui_story_30360601_30_dialog_content = "Aproxime-se. Não há nada para ter medo.",
  ui_story_30360601_31_dialog_content = "Esse cara provavelmente tem amigos por aqui, então certifique-se de prestar atenção no que ele diz.",
  ui_story_30360601_32_dialog_content = "<color=#e8d9bb>Um armazém sujo e deteriorado passa pela mente do lobo, assim como inúmeros outros lobos trancados em gaiolas.</color>",
  ui_story_30360601_33_dialog_content = "<color=#e8d9bb>Além disso, uma série de cenas ainda mais brutais vêm à vista—</color>",
  ui_story_30360601_34_dialog_content = "H-Hydrad...",
  ui_story_30360601_35_dialog_content = "Que foi? Você tá bem?",
  ui_story_30360601_36_dialog_content = "Ei! Sai dessa, PlayerName!",
  ui_story_30360601_37_dialog_content = "E-Eu estou bem, apenas vi um monte de memórias realmente terríveis de uma vez... Desculpe se te preocupei.",
  ui_story_30360601_38_dialog_content = "Não, é minha culpa. Eu não deveria ter pedido para você se envolver quando estava apenas passando.",
  ui_story_30360601_39_dialog_content = "Está tudo bem, sério! Isso também não é a primeira vez que acontece comigo...",
  ui_story_30360601_40_dialog_content = "De qualquer forma, há coisas mais importantes para se preocupar! Este lobo precisa da nossa ajuda, Hydrad!",
  ui_story_30360601_41_dialog_content = "Você estava certo. Este lobo e sua alcateia foram capturados e trazidos aqui contra a sua vontade, mas este conseguiu escapar.",
  ui_story_30360601_42_dialog_content = "Eles estavam sendo mantidos em algum armazém sujo. Além disso...",
  ui_story_30360601_43_dialog_content = "As pessoas que os mantinham lá eram terríveis. Eles não se importavam com a vida desses lobos de forma alguma.",
  ui_story_30360601_44_dialog_content = "... Eu tenho uma ideia bastante boa de que tipo de pessoas estão por trás disso. Gangues como a deles foram endireitadas no passado, mas alguns deles estão tentando trazer de volta os velhos tempos.",
  ui_story_30360601_45_dialog_content = "E infelizmente, sempre haverá pessoas ricas com mau gosto para financiar suas operações.",
  ui_story_30360601_46_dialog_content = "Eu não vou deixar eles se safarem com isso.",
  ui_story_30360601_47_dialog_content = "O que você está planejando fazer, Hydrad?",
  ui_story_30360601_48_dialog_content = "Você disse que viu um monte de memórias terríveis agora, certo? Isso me diz que não há tempo a perder se eu quiser salvar suas vidas.",
  ui_story_30360601_49_dialog_content = "Tudo bem, lobo, preste atenção. Se você quer resgatar seus amigos, então terá que trabalhar comigo.",
  ui_story_30360601_50_dialog_content = "Diga para ele me seguir para que eu possa ajudá-lo.",
  ui_story_30360601_51_dialog_content = "Apenas deixe comigo.",
  ui_story_30360601_52_dialog_content = "Agora eu só preciso me trocar. Me dê um minuto.",
  ui_story_30360601_53_dialog_content = "Hydrad? Ele saiu tão rápido... Será que ele já tem um plano?",
  ui_story_30360601_54_dialog_content = "<color=#e8d9bb>Pouco depois-</color>",
  ui_story_30360601_55_dialog_content = "Voltei, agora o que você acha?",
  ui_story_30360601_56_dialog_content = "Pareço exatamente como um rico sem cérebro agora, né?",
  ui_story_30360601_57_dialog_content = "Hydrad, você...",
  ui_story_30360601_58_dialog_content = "Você está tão legal agora! Quer dizer, ainda mais legal do que antes! De qualquer forma, é completamente diferente do seu estilo habitual.",
  ui_story_30360601_59_dialog_content = "(Não tenho certeza se ele realmente se encaixa no papel de um \"rico sem cérebro\", mas isso deve servir como disfarce.)",
  ui_story_30360601_60_dialog_content = "Com apenas alguns retoques finais, vou fazer parecer que sou o dono deste lobo...",
  ui_story_30360601_61_dialog_content = "Lá. Assim que me virem andando pelas ruas com isso, tenho certeza de que essas hienas sairão rastejando.",
  ui_story_30360601_62_dialog_content = "Enquanto eu faço isso, preciso que você sinta a localização da matilha deste lobo, PlayerName.",
  ui_story_30360601_63_dialog_content = "Não quero expô-lo a nenhum perigo, mas sentir a área não deve ser um problema, certo?",
  ui_story_30360601_64_dialog_content = "Se me vir indo a algum lugar com outra pessoa, alerte o Shadowlord imediatamente.",
  ui_story_30360601_65_dialog_content = "Esses caras acham que podem se esconder nas sombras, mas com a sua ajuda, com certeza vamos desmascará-los.",
  ui_story_30360601_66_dialog_content = "Prometo que farei o meu melhor, Hydrad.",
  ui_story_30360601_67_dialog_content = "Espere, o que você—ei!",
  ui_story_30360601_68_dialog_content = "Pronto. Você já parece não ser uma ameaça, então apenas esconda seu rosto com seu chapéu, e ninguém vai notar você.",
  ui_story_30360601_69_dialog_content = "Estou saindo. O resto está em suas mãos agora.",
  ui_story_30360601_70_dialog_content = "T-Tudo bem! Não decepcione o Hydrad, não decepcione o Hydrad, não decepcione—",
  ui_story_30360601_71_dialog_content = "Sobre o que você está resmungando ali?",
  ui_story_30360601_72_dialog_content = "Não importa, é hora de ir.",
  ui_story_30360601_73_dialog_content = "Você passou por um inferno, não passou?",
  ui_story_30360601_74_dialog_content = "Awooo—",
  ui_story_30360601_75_dialog_content = "Aguente só um pouco mais. Você terá sua vingança em breve.",
  ui_story_30360601_76_dialog_content = "<color=#e8d9bb>Um tempo depois—</color>",
  ui_story_30360601_77_dialog_content = "Um lobo vivo, hein? Esse é um bicho de estimação e tanto que você tem aí, amigo.",
  ui_story_30360601_78_dialog_content = "Sim? O que é isso para você?",
  ui_story_30360601_79_dialog_content = "Não precisa ser rude, amigo! Posso ver que você tem bom gosto, posso te interessar em algumas das nossas novidades?",
  ui_story_30360601_80_dialog_content = "Tem algum de cor sólida? Os casacos deles também devem ser brilhantes.",
  ui_story_30360601_81_dialog_content = "Eu estava certo - você realmente sabe das coisas! Nós temos tudo isso e muito mais, meu amigo!",
  ui_story_30360601_82_dialog_content = "Nossos melhores exemplares têm pelos tão brilhantes quanto óleo, e são tão ferozes quanto possível!",
  ui_story_30360601_83_dialog_content = "Assim que você vê-los, saberá que são os lobos de combate perfeitos. Eles só parecem assim por causa de quão fortes eles são!",
  ui_story_30360601_84_dialog_content = "Seu povo não está preocupado com o Senhor Sombrio?",
  ui_story_30360601_85_dialog_content = "Esses idiotas em Lumopolis são muito covardes para descer aqui apenas para comprar animais selvagens, então quem exatamente são seus clientes?",
  ui_story_30360601_86_dialog_content = "Hahaha, você está fazendo muitas perguntas aí, amigo!",
  ui_story_30360601_87_dialog_content = "A única maneira de contrabandear esses lobos para esta cidade sem alertar a Guilda Umbraton era sedando-os durante todo o caminho.",
  ui_story_30360601_88_dialog_content = "Heh, isso significa que eles não comem há dias, certo? Isso não vai fazer nenhum favor para seus pelos brilhantes.",
  ui_story_30360601_89_dialog_content = "Ei, amigo... Quem exatamente é você?",
  ui_story_30360601_90_dialog_content = "Apenas alguém que trabalha em um campo semelhante e se interessa pela sua pequena operação, é só isso.",
  ui_story_30360601_91_dialog_content = "Então você não está planejando comprar nenhum dos nossos lobos?",
  ui_story_30360601_92_dialog_content = "Não, obrigado. Eu já tenho o suficiente.",
  ui_story_30360601_93_dialog_content = "Tsk, tentando se meter no nosso negócio, hein? Com quem você pensa que está falando, punk?",
  ui_story_30360601_94_dialog_content = "É sempre melhor compartilhar a riqueza, não acha?",
  ui_story_30360601_95_dialog_content = "Ouviram isso, rapazes? Parece que temos um verdadeiro comediante aqui!",
  ui_story_30360601_96_dialog_content = "Você escolheu as pessoas erradas para mexer hoje, criança. Agora me diga para quem você trabalha!",
  ui_story_30360601_97_dialog_content = "Já é difícil o suficiente fazer negócios em Umbraton. Com pessoas como você, como é que vamos conseguir sobreviver aqui?",
  ui_story_30360601_98_dialog_content = "Eu deveria me importar?",
  ui_story_30360601_99_dialog_content = "Cerquem-no! Se você não quer se machucar, então sugiro que venha em silêncio.",
  ui_story_30360601_100_dialog_content = "Você não quer morrer, quer?",
  ui_story_30360601_101_dialog_content = "... Então tá.",
  ui_story_30360601_102_dialog_content = "<color=#e8d9bb>Os contrabandistas aprisionam Hydrad em seu armazém, onde ele permanece por um dolorosamente longo tempo.</color>",
  ui_story_30360601_103_dialog_content = "Você é mais resistente do que parece, criança. Mesmo depois de apanhar desse jeito, ainda não está disposto a desistir dos seus amigos?",
  ui_story_30360601_104_dialog_content = "Quem diabos você pensa que é, procurando briga conosco em nosso território...",
  ui_story_30360601_105_dialog_content = "Chefe, olha o que encontramos quando tiramos a coleira do lobo! É o mesmo que escapou mais cedo!",
  ui_story_30360601_106_dialog_content = "Droga, eu sabia que encontrar esse cara na rua era bom demais para ser verdade!",
  ui_story_30360601_107_dialog_content = "É isso tudo de vocês? Também não há muitos lobos aqui... Isso é realmente tudo do seu \"mercadoria\" também?",
  ui_story_30360601_108_dialog_content = "Se for assim, sugiro que desista antes que meu amigo decida aparecer.",
  ui_story_30360601_109_dialog_content = "Você tem um desejo de morte, amigo? Você deveria saber, os <color=#FFB400>Spearows</color> nos deixam conduzir nossa operação em seu território, e—",
  ui_story_30360601_110_dialog_content = "Quieto, idiota! Supostamente deveríamos estar interrogando ele!",
  ui_story_30360601_111_dialog_content = "Droga, então parece que vamos ter que parar de brincar.",
  ui_story_30360601_112_dialog_content = "Salve isso. Eu não sou nada como vocês, palhaços.",
  ui_story_30360601_113_dialog_content = "Isso é porque eu confio naquele cara... meu amigo, isto é.",
  ui_story_30360601_114_dialog_content = "O que houve?",
  ui_story_30360601_115_dialog_content = "Estamos ferrados, chefe! O Senhor Sombrio está aqui, e seu povo também...",
  ui_story_30360601_116_dialog_content = "O-O que?",
  ui_story_30360601_117_dialog_content = "Heh, demoraram bastante.",
  ui_story_30360601_118_dialog_content = "Esqueça esse cara, chefe! Ainda podemos escapar pela porta dos fundos!",
  ui_story_30360601_119_dialog_content = "Nem pense.",
  ui_story_30360601_120_dialog_content = "Estou cansado de esperar—saia, Lobos Sombrios!",
  ui_story_30360601_121_dialog_content = "De onde vieram essas coisas?",
  ui_story_30360601_122_dialog_content = "Cuidado, chefe! A criança conseguiu se libertar!",
  ui_story_30360601_123_dialog_content = "Agora é hora de uma lição de dor - e os <color=#FFB400>lobos</color> vão te ensinar!",
  ui_story_30360601_124_dialog_content = "S-Fique atrás!",
  ui_story_30360601_125_dialog_content = "Chefe!",
  ui_story_30360601_126_dialog_content = "É melhor eu terminar isso antes que PlayerName chegue aqui. Eu não quero que ele veja o que está prestes a acontecer.",
  ui_story_30360601_127_dialog_content = "<color=#e8d9bb>Algum tempo depois.</color>",
  ui_story_30360601_128_dialog_content = "Obrigado novamente pela sua ajuda.",
  ui_story_30360601_129_option_content = "Não mencione isso. Eu nem mesmo entrei antes de me dizerem que já havia acabado.",
  ui_story_30360601_130_dialog_content = "Sério? Isso é bom.",
  ui_story_30360601_131_option_content = "Não sei, apenas sinto que não fiz muito.",
  ui_story_30360601_132_dialog_content = "Sem você, este plano nunca teria funcionado.",
  ui_story_30360601_133_dialog_content = "Eles tinham números, bem como uma rota de fuga.",
  ui_story_30360601_134_dialog_content = "Porque você levou o Shadowlord até aqui, conseguimos prender todos eles em um só lugar.",
  ui_story_30360601_135_dialog_content = "Ah, heheh... Tenho certeza de que você está apenas me lisonjeando, mas estou feliz em poder ajudar!",
  ui_story_30360601_136_dialog_content = "Não, você definitivamente é digno da minha confiança. Na verdade, a presença da sua sombra combina ainda melhor comigo agora.",
  ui_story_30360601_137_dialog_content = "Aliás, aquele lobo de antes se reuniu com sua alcateia, e eles serão enviados de volta para casa em breve.",
  ui_story_30360601_138_dialog_content = "Afinal, é sempre melhor para animais de bando ficarem juntos.",
  ui_story_30360601_139_dialog_content = "Isso também vale para você, Hydrad. Você e o Senhor das Sombras formam uma excelente equipe!",
  ui_story_30360601_140_dialog_content = "... De qualquer forma, me pergunto o que acontecerá com o resto dos Spearows que estavam envolvidos neste anel de contrabando.",
  ui_story_30360601_141_dialog_content = "Aquele polvo fedorento é responsável por lidar com eles, então quem sabe quando as coisas serão resolvidas?",
  ui_story_30360601_142_dialog_content = "Mas isso não importa agora. Vamos lá, vamos.",
  ui_story_30360601_143_dialog_content = "Huh? Onde estamos indo?",
  ui_story_30360601_144_dialog_content = "Você estava fazendo algo antes de nos encontrarmos, não estava? Eu estava muito ocupado com esse negócio de lobo para ouvir você.",
  ui_story_30360601_145_dialog_content = "Você me ajudou, então agora é a minha vez de te ajudar.",
  ui_story_30360601_146_dialog_content = "Agora vamos. Seja lá o que for que você precisa fazer, estarei lá para te dar uma mão.",
  ui_story_30360601_147_dialog_content = "Então, qual é o plano?"
}
return config
